// Sell held positions with reduce_only V2 orders (can only shrink a position, never flip it).
// Plan: JSON [{t, side: held side 'yes'|'no', q, mode: 'bid' | 'top'}]
//   mode 'bid' -> sell at the current held-side bid (taker)
//   mode 'top' -> sell at 99.9c on deci-capable books, else 99c (fills if bid is there, else rests)
// Quotes: JSON {ticker: {pls, yb, ya, nb, na}} from GET /markets (dollar strings).
// Usage: node .llm/sell-positions.mjs <plan.json> <quotes.json> [--go]
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const {ValidatedKalshiBulkOrderPlacer} = await import(path.join(here, '../packages/cli/dist/validation/api-validator.js'));

const [planPath, quotesPath, flag] = process.argv.slice(2);
const go = flag === '--go';
const plan = JSON.parse(fs.readFileSync(planPath, 'utf8'));
const quotes = JSON.parse(fs.readFileSync(quotesPath, 'utf8'));
const client = ValidatedKalshiBulkOrderPlacer.fromEnvironment(false);

const DECI = new Set(['tapered_deci_cent', 'deci_cent']);
const toCents = (d) => Math.round(Number(d) * 1000) / 10;

const results = [];
for (const p of plan) {
	const q = quotes[p.t];
	if (!q) throw new Error(`no quote for ${p.t}`);
	const heldBid = p.side === 'no' ? toCents(q.nb) : toCents(q.yb);
	let sellCents;
	if (p.mode === 'bid') {
		if (!(heldBid > 0)) throw new Error(`${p.t}: no ${p.side} bid to sell into`);
		sellCents = heldBid;
	} else {
		sellCents = DECI.has(q.pls) ? 99.9 : 99;
	}
	// Selling held NO at N = YES bid at 100-N; selling held YES at Y = YES ask at Y.
	const yesCents = p.side === 'no' ? Math.round((100 - sellCents) * 10) / 10 : sellCents;
	const request = {
		ticker: p.t,
		side: p.side === 'no' ? 'bid' : 'ask',
		count: Number(p.q).toFixed(2),
		price: (yesCents / 100).toFixed(4),
		reduce_only: true,
	};
	const line = `${p.t.padEnd(34)} sell ${p.side.padEnd(3)} ${request.count.padStart(8)} @ ${sellCents}c (bid ${heldBid}c, ${q.pls}) -> V2 ${request.side} ${request.price}`;
	if (!go) {
		console.log(`DRY ${line}`);
		continue;
	}
	try {
		const resp = await client.createOrderV2(request);
		const o = resp.data.order ?? resp.data;
		console.log(`OK  ${line} status=${o.status ?? '?'} filled=${o.fill_count_fp ?? o.fill_count ?? '?'}`);
		results.push({t: p.t, ok: true, order: o});
	} catch (error) {
		console.log(`ERR ${line} ${error.message}`);
		results.push({t: p.t, ok: false, error: error.message});
	}
}
if (go) fs.writeFileSync(path.join(path.dirname(planPath), 'sell-results.json'), JSON.stringify(results, null, 1));

